  await delay(5);
  console.log('1 already idle:', done);
}

// 2. basic wait
{
  const limit = pLimit(1);
  let done = false;
  const p = limit(() => delay(50));
  limit.onIdle().then(() => { done = true; });
  await delay(20);
  console.log('2 before done:', done, 'active', limit.activeCount);
  await p;
  await delay(5);
  console.log('2 after done:', done, 'active', limit.activeCount);
}

// 3. multiple waiters + rejected job
{
  const limit = pLimit(2);
  const results = [];
  limit.onIdle().then(() => results.push('a'));
  limit(() => { throw new Error('x'); }).catch(() => {});
  limit(() => delay(20)).catch(() => {});
  limit.onIdle().then(() => results.push('b'));
  await limit.onIdle();
  console.log('3 results:', results);
}

// 4. clearQueue rejectOnClear:false with no active
{
  const limit = pLimit(1);
  let idle = false;
  const pending = limit(() => delay(1000)); // active
  const discarded = limit(() => delay(1000)); // queued
  limit.clearQueue();
  limit.onIdle().then(() => { idle = true; });
  await delay(20);
  console.log('4 idle while active:', idle, 'active', limit.activeCount);
  await pending;
  await limit.onIdle();
  console.log('4 idle after active done:', idle);
  discarded.catch(() => {});
}

// 5. resolving job enqueues another
{
  const limit = pLimit(1);
  const order = [];
  const first = limit(() => { order.push('first'); return 'v'; });
  first.then(() => {
    order.push('enqueue');
    limit(async () => { order.push('second-start'); await delay(20); order.push('second-end'); });
  });
  await limit.onIdle();
  console.log('5 order:', order);
}

// 6. limitFunction onIdle
{
  const lf = limitFunction(async () => delay(10), {concurrency: 1});
  let done = false;
  const p = lf();
  lf.onIdle().then(() => { done = true; });
  await p;
  await delay(5);
  console.log('6 limitFunction idle:', done, typeof lf.onIdle);
}

// 7. job enqueues synchronously within itself (reserved)
{
  const limit = pLimit(1);
  const order = [];
  let inner;
  const outer = limit(async () => {
    order.push('outer-start');
    inner = limit(() => { order.push('inner'); });
    order.push('outer-end');
  });
  await limit.onIdle();
  console.log('7 order:', order, 'inner pending?', limit.pendingCount);
  await inner.catch(()=>{});
}
