import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately when the limiter is already idle', async t => {
	const limit = pLimit(1);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle resolves after all active jobs finish', async t => {
	const limit = pLimit(1);
	let idle = false;

	const running = limit(() => delay(50));
	limit.onIdle().then(() => {
		idle = true;
	});

	await delay(10);
	t.false(idle);
	t.is(limit.activeCount, 1);

	await running;
	await limit.onIdle();
	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle waits for both running and queued jobs', async t => {
	const limit = pLimit(2);
	const order = [];

	const promises = [
		limit(async () => {
			await delay(30);
			order.push('a');
		}),
		limit(async () => {
			await delay(60);
			order.push('b');
		}),
		limit(async () => {
			await delay(90);
			order.push('c');
		}),
	];

	await limit.onIdle();
	order.push('idle');

	t.deepEqual(order, ['a', 'b', 'c', 'idle']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all(promises);
});

test('onIdle supports multiple waiters', async t => {
	const limit = pLimit(1);
	const resolved = [];

	const running = limit(() => delay(30));

	const first = limit.onIdle().then(() => resolved.push('first'));
	const second = limit.onIdle().then(() => resolved.push('second'));
	const third = limit.onIdle().then(() => resolved.push('third'));

	await Promise.all([first, second, third]);
	t.deepEqual(resolved, ['first', 'second', 'third']);
	t.is(limit.activeCount, 0);

	await running;
});

test('onIdle resolves when a job rejects', async t => {
	const limit = pLimit(2);
	const error = new Error('🦄');
	let idle = false;

	const rejecting = limit(async () => {
		await delay(20);
		throw error;
	}).catch(() => {});

	const resolving = limit(() => delay(30));

	limit.onIdle().then(() => {
		idle = true;
	});

	await delay(10);
	t.false(idle);

	await Promise.all([rejecting, resolving]);
	await limit.onIdle();
	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle does not treat reserved slots as idle', async t => {
	const limit = pLimit(1);
	let idle = false;

	const running = limit(() => delay(30));
	t.is(limit.activeCount, 1);

	limit.onIdle().then(() => {
		idle = true;
	});

	await delay(10);
	t.false(idle);

	await running;
	await limit.onIdle();
	t.true(idle);
});

test('onIdle does not report idle early when a resolved job enqueues another', async t => {
	const limit = pLimit(1);
	const order = [];

	const first = limit(() => {
		order.push('first');
		return 'value';
	});

	first.then(() => {
		order.push('enqueue');
		limit(async () => {
			order.push('second:start');
			await delay(30);
			order.push('second:end');
		});
	});

	await limit.onIdle();
	order.push('idle');

	t.deepEqual(order, ['first', 'enqueue', 'second:start', 'second:end', 'idle']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle does not report idle early when a job enqueues from within itself', async t => {
	const limit = pLimit(1);
	const order = [];

	let inner;
	const outer = limit(async () => {
		order.push('outer:start');
		inner = limit(() => order.push('inner'));
		order.push('outer:end');
	});

	await limit.onIdle();
	order.push('idle');

	t.deepEqual(order, ['outer:start', 'outer:end', 'inner', 'idle']);
	t.is(limit.activeCount, 0);

	await Promise.all([outer, inner]);
});

test('clearQueue releases onIdle waiters when the queue is drained and nothing is running', async t => {
	const limit = pLimit(1);

	Array.from({length: 3}, () => limit(() => delay(1000)));
	await Promise.resolve();

	t.is(limit.activeCount, 1);
	t.is(limit.pendingCount, 3);

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	// Even though the discarded promises stay unresolved (rejectOnClear defaults to false),
	// onIdle must resolve once the queue is empty... but only after the running job finishes.
	let idle = false;
	limit.onIdle().then(() => {
		idle = true;
	});

	await delay(10);
	t.false(idle);
	t.is(limit.activeCount, 1);
});

test('clearQueue with no active jobs releases onIdle waiters even when discarded promises stay unresolved', async t => {
	const limit = pLimit(1);

	const running = limit(() => delay(50));
	const discardedOne = limit(() => delay(1000));
	const discardedTwo = limit(() => delay(1000));

	await delay(10);
	t.is(limit.activeCount, 1);
	t.is(limit.pendingCount, 2);

	let idle = false;
	const idlePromise = limit.onIdle().then(() => {
		idle = true;
	});

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	// The running job is still active, so the limiter is not idle yet.
	await delay(10);
	t.false(idle);

	await running;
	await idlePromise;

	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	// Keep the discarded promises from becoming unhandled rejections if they ever settle.
	discardedOne.catch(() => {});
	discardedTwo.catch(() => {});
});

test('clearQueue with no active jobs resolves onIdle after draining the queue', async t => {
	const limit = pLimit(2);

	const first = limit(() => delay(1000));
	const second = limit(() => delay(1000));
	const queuedOne = limit(() => delay(1000));
	const queuedTwo = limit(() => delay(1000));

	// Let the first two start so the other two are queued.
	await Promise.resolve();
	t.is(limit.activeCount, 2);
	t.is(limit.pendingCount, 2);

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	let idle = false;
	const idlePromise = limit.onIdle().then(() => {
		idle = true;
	});

	await delay(10);
	t.false(idle);

	await Promise.all([first, second]);
	await idlePromise;
	t.true(idle);
	t.is(limit.activeCount, 0);

	queuedOne.catch(() => {});
	queuedTwo.catch(() => {});
});

test('onIdle reflects concurrency changes and preserves them', async t => {
	const limit = pLimit(1);
	const order = [];

	const promises = Array.from({length: 4}, (_, index) => limit(async () => {
		order.push(`job${index}`);
		await delay(10);
	}));

	// All four are scheduled; only one runs at a time initially.
	t.is(limit.concurrency, 1);

	limit.concurrency = 4;
	await limit.onIdle();

	t.is(limit.concurrency, 4);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all(promises);
	// FIFO is preserved even with the concurrency change.
	t.deepEqual(order, ['job0', 'job1', 'job2', 'job3']);
});

test('onIdle is exposed on the limitFunction wrapper', async t => {
	const limitedFunction = limitFunction(async () => delay(30), {concurrency: 1});

	t.is(typeof limitedFunction.onIdle, 'function');

	let idle = false;
	const running = limitedFunction();
	limitedFunction.onIdle().then(() => {
		idle = true;
	});

	await delay(10);
	t.false(idle);

	await running;
	await limitedFunction.onIdle();
	t.true(idle);
});

test('onIdle on limitFunction waits for queued calls', async t => {
	const limitedFunction = limitFunction(async value => {
		await delay(20);
		return value;
	}, {concurrency: 1});

	const results = [limitedFunction(1), limitedFunction(2), limitedFunction(3)];

	await limitedFunction.onIdle();

	t.deepEqual(await Promise.all(results), [1, 2, 3]);
});

test('onIdle resolves normally on an idle limitFunction', async t => {
	const limitedFunction = limitFunction(async () => {}, {concurrency: 1});

	await t.notThrowsAsync(limitedFunction.onIdle());
});

test('map can be awaited with onIdle', async t => {
	const limit = pLimit(2);
	const results = await limit.map([1, 2, 3, 4], async value => {
		await delay(10);
		return value * 2;
	});

	await limit.onIdle();

	t.deepEqual(results, [2, 4, 6, 8]);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

