import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately when the limiter is already idle', async t => {
	const limit = pLimit(1);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle resolves after all active jobs finish', async t => {
	const limit = pLimit(1);
	let idle = false;

	const running = limit(() => delay(50));
	const idlePromise = (async () => {
		await limit.onIdle();
		idle = true;
	})();

	await delay(10);
	t.false(idle);
	t.is(limit.activeCount, 1);

	await running;
	await idlePromise;
	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle waits for both running and queued jobs', async t => {
	const limit = pLimit(2);
	const order = [];

	const promises = [
		limit(async () => {
			await delay(30);
			order.push('a');
		}),
		limit(async () => {
			await delay(60);
			order.push('b');
		}),
		limit(async () => {
			await delay(90);
			order.push('c');
		}),
	];

	await limit.onIdle();
	order.push('idle');

	t.deepEqual(order, ['a', 'b', 'c', 'idle']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all(promises);
});

test('onIdle supports multiple waiters', async t => {
	const limit = pLimit(1);
	const resolved = [];

	const running = limit(() => delay(30));

	const first = (async () => {
		await limit.onIdle();
		resolved.push('first');
	})();
	const second = (async () => {
		await limit.onIdle();
		resolved.push('second');
	})();
	const third = (async () => {
		await limit.onIdle();
		resolved.push('third');
	})();

	await Promise.all([first, second, third]);
	t.deepEqual(resolved, ['first', 'second', 'third']);
	t.is(limit.activeCount, 0);

	await running;
});

test('onIdle resolves when a job rejects', async t => {
	const limit = pLimit(2);
	const error = new Error('🦄');
	let idle = false;

	const rejecting = limit(async () => {
		await delay(20);
		throw error;
	}).catch(() => {});

	const resolving = limit(() => delay(30));

	const idlePromise = (async () => {
		await limit.onIdle();
		idle = true;
	})();

	await delay(10);
	t.false(idle);

	await Promise.all([rejecting, resolving]);
	await idlePromise;
	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle does not treat reserved slots as idle', async t => {
	const limit = pLimit(1);
	let idle = false;

	const running = limit(() => delay(30));
	t.is(limit.activeCount, 1);

	const idlePromise = (async () => {
		await limit.onIdle();
		idle = true;
	})();

	await delay(10);
	t.false(idle);

	await running;
	await idlePromise;
	t.true(idle);
});

test('onIdle does not report idle early when a resolved job enqueues another', async t => {
	const limit = pLimit(1);
	const order = [];

	const first = limit(() => {
		order.push('first');
		return 'value';
	});

	const followUp = (async () => {
		await first;
		order.push('enqueue');
		await limit(async () => {
			order.push('second:start');
			await delay(30);
			order.push('second:end');
		});
	})();

	await limit.onIdle();
	order.push('idle');

	t.deepEqual(order, ['first', 'enqueue', 'second:start', 'second:end', 'idle']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await followUp;
});

test('onIdle does not report idle early when a job enqueues from within itself', async t => {
	const limit = pLimit(1);
	const order = [];

	let inner;
	const outer = limit(async () => {
		order.push('outer:start');
		inner = limit(() => order.push('inner'));
		order.push('outer:end');
	});

	await limit.onIdle();
	order.push('idle');

	t.deepEqual(order, ['outer:start', 'outer:end', 'inner', 'idle']);
	t.is(limit.activeCount, 0);

	await Promise.all([outer, inner]);
});

test('clearQueue with a running job still waits for it before reporting idle', async t => {
	const limit = pLimit(1);

	const running = limit(() => delay(60));
	const queuedOne = limit(() => delay(1000));
	const queuedTwo = limit(() => delay(1000));
	const queuedThree = limit(() => delay(1000));

	await delay(10);
	t.is(limit.activeCount, 1);
	t.is(limit.pendingCount, 3);

	let idle = false;
	const idlePromise = (async () => {
		await limit.onIdle();
		idle = true;
	})();

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	// The running job is still active, so the limiter is not idle yet.
	await delay(10);
	t.false(idle);

	await running;
	await idlePromise;

	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	// Keep the discarded promises from becoming unhandled rejections if they ever settle.
	queuedOne.catch(() => {});
	queuedTwo.catch(() => {});
	queuedThree.catch(() => {});
});

test('clearQueue releases onIdle waiters when the queue is drained and nothing is running', async t => {
	const limit = pLimit(2);

	const runningOne = limit(() => delay(60));
	const runningTwo = limit(() => delay(60));
	const queuedOne = limit(() => delay(1000));
	const queuedTwo = limit(() => delay(1000));

	// Let the first two start so the other two are queued.
	await Promise.resolve();
	t.is(limit.activeCount, 2);
	t.is(limit.pendingCount, 2);

	let idle = false;
	const idlePromise = (async () => {
		await limit.onIdle();
		idle = true;
	})();

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	// Runs are still active, so the limiter is not idle.
	await delay(10);
	t.false(idle);

	await Promise.all([runningOne, runningTwo]);
	await idlePromise;

	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	queuedOne.catch(() => {});
	queuedTwo.catch(() => {});
});

test('onIdle resolves after clearQueue drains an unresolvable queue with no active jobs', async t => {
	const limit = pLimit(1);

	// These never resolve (their internals are discarded before running).
	const discarded = Array.from({length: 3}, () => limit(() => delay(1000).then(() => 'never')));

	// Give the first job a chance to start, then discard the rest.
	await Promise.resolve();
	limit.clearQueue();

	// The first job is running; onIdle must wait for it.
	await limit.onIdle();
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	for (const promise of discarded) {
		promise.catch(() => {});
	}
});

